import { api } from "encore.dev/api";
import { createSchema, createYoga } from "graphql-yoga";

// GraphQL schema with a single `hello` query.
const typeDefs = /* GraphQL */ `
  type Query {
    """
    Returns a greeting for the provided name.
    If no name is provided, it returns a greeting for "World".
    """
    hello(name: String): String!
  }
`;

// Resolvers for the schema.
const resolvers = {
  Query: {
    hello: (_: unknown, args: { name?: string | null }): string => {
      const name = args.name && args.name.length > 0 ? args.name : "World";
      return `Hello, ${name}!`;
    },
  },
};

// Build the GraphQL schema.
const schema = createSchema({ typeDefs, resolvers });

// Create a Yoga instance configured to expose the schema at /graphql.
const yoga = createYoga({
  schema,
  graphqlEndpoint: "/graphql",
  // Yoga will figure out the request method on its own.
  fetch: fetch,
});

// Encore raw endpoint that delegates incoming HTTP requests to Yoga.
// Using `api.raw` lets us pass the full Request object to the GraphQL handler
// (handles POST with JSON bodies, GET with query params, etc.).
export const graphqlHandler = api.raw(
  { expose: true, path: "/graphql", method: "*" },
  async (req: Request): Promise<Response> => {
    return yoga.fetch(req);
  },
);

